Usage example: //-----Theclient-----

//Createasocketandconnectitto192.168.1.50onport55001
sf::TcpSocketsocket;
socket.connect("192.168.1.50",55001);

//Sendamessagetotheconnectedhost
std::stringmessage="Hi,Iamaclient";
socket.send(message.c_str(),message.size()+1);

//Receiveananswerfromtheserver
std::array<char,1024>buffer;
std::size_treceived=0;
socket.receive(buffer.data(),buffer.size(),received);
std::cout<<"Theserversaid:"<<buffer.data()<<std::endl;

//-----Theserver-----

//Createalistenertowaitforincomingconnectionsonport55001
sf::TcpListenerlistener;
listener.listen(55001);

//Waitforaconnection
sf::TcpSocketsocket;
listener.accept(socket);
std::cout<<"Newclientconnected:"<<socket.getRemoteAddress().value()<<std::endl;

//Receiveamessagefromtheclient
std::array<char,1024>buffer;
std::size_treceived=0;
socket.receive(buffer.data(),buffer.size(),received);
std::cout<<"Theclientsaid:"<<buffer.data()<<std::endl;

//Sendananswer
std::stringmessage="Welcome,client";
socket.send(message.c_str(),message.size()+1);
